SELECT s.id, s.candle_open_time, s.generated_at, s.decision, s.original_decision, s.total_score, s.confidence_score, s.final_entry_allowed, s.atr_immediate_entry_allowed, s.latest_price, s.stop_loss, s.take_profit FROM trade_signal s WHERE s.symbol = 'EGLDUSDT' AND s.interval_code = '1m' AND s.generated_at BETWEEN '2026-10-11 22:09:00' AND '2026-10-11 22:40:02' ORDER BY s.generated_at LIMIT 40